const C = $('CONFIG').first().json;
const req = $json;
const body = req.body || {};
const fail = (status, errors) => [{ json: { valid: false, http_status: status, errors } }];

// 1. Optional shared-secret check (blank GATEWAY_AUTH_TOKEN = open gateway)
if (C.GATEWAY_AUTH_TOKEN && (req.headers || {})['x-gateway-token'] !== C.GATEWAY_AUTH_TOKEN) {
  return fail(401, ['unauthorized']);
}

// 2. CONFIG sanity (a broken config should say so, not fail mysteriously)
let providers;
try { providers = JSON.parse(C.PROVIDERS_JSON); } catch (err) { return fail(500, ['CONFIG.PROVIDERS_JSON is not valid JSON']); }
try { JSON.parse(C.STATE_API_HEADERS_JSON || '{}'); } catch (err) { return fail(500, ['CONFIG.STATE_API_HEADERS_JSON is not valid JSON']); }
for (const k of ['BREAKER_API_URL', 'RATE_LIMIT_API_URL', 'CACHE_API_URL']) {
  if (!/^https?:\/\//.test(C[k] || '')) return fail(500, [`CONFIG.${k} must start with http:// or https://`]);
}

// 3. Request validation
const errors = [];
const integration = body.integration;
if (typeof integration !== 'string' || !/^[A-Za-z0-9_-]{1,64}$/.test(integration)) {
  errors.push('integration is required (letters, digits, - and _ only)');
} else if (!Object.prototype.hasOwnProperty.call(providers, integration)) {
  errors.push(`integration "${integration}" is not defined in CONFIG.PROVIDERS_JSON`);
} else {
  const p = providers[integration] || {};
  const rl = p.rate_limit || {};
  if (!/^https?:\/\//.test(p.base_url || '')) errors.push(`provider "${integration}" needs a base_url starting with http:// or https://`);
  if (!(rl.capacity > 0) || !(rl.refill_per_second > 0)) errors.push(`provider "${integration}" needs rate_limit.capacity and rate_limit.refill_per_second (positive numbers)`);
  if (errors.length) return fail(500, errors); // our config is wrong, not the caller
}

let resource_path = body.resource_path;
if (typeof resource_path !== 'string' || !resource_path.length) {
  errors.push('resource_path is required');
} else {
  resource_path = resource_path.replace(/^\/+/, '');
  if (/\.\.|:\/\/|[?#\\\s]/.test(resource_path)) errors.push('resource_path must be a plain path (no "..", "://", "?", "#", spaces or backslashes; pass query values in params)');
}
if (body.params !== undefined && (body.params === null || typeof body.params !== 'object' || Array.isArray(body.params))) errors.push('params must be an object');
if (typeof body.cache_key !== 'string' || !body.cache_key.length || body.cache_key.length > 200) errors.push('cache_key is required (string, max 200 characters)');
const ms = body.max_staleness_seconds;
if (ms !== undefined && ms !== null && !(typeof ms === 'number' && isFinite(ms) && ms >= 0)) errors.push('max_staleness_seconds must be a number >= 0');
if (errors.length) return fail(400, errors);

return [{ json: { valid: true, errors: [], http_status: 200,
  integration, resource_path, params: body.params || {},
  cache_key: integration + '__' + body.cache_key,   // namespaced so two integrations can never collide
  max_staleness_seconds: ms ?? null } }];

const t = $json;
const found = t.statusCode >= 200 && t.statusCode < 300;
const state = found ? (t.body || {}) : {};
const status = state.status || 'closed'; // closed | open
const now = Date.now();
let breaker_status;
if (status === 'closed') breaker_status = 'closed';
else if (now >= (state.next_probe_at || 0)) breaker_status = 'open_due_probe';
else breaker_status = 'open_no_probe';
return [{ json: { integration: t.integration, resource_path: t.resource_path, params: t.params,
  cache_key: t.cache_key, max_staleness_seconds: t.max_staleness_seconds,
  breaker_status, next_probe_at: state.next_probe_at || null, trip_count: state.trip_count || 0 } }];

const C = $('CONFIG').first().json;
const t = $json;
const body = (t.statusCode >= 200 && t.statusCode < 300) ? (t.body || {}) : {};
return [{ json: { integration: t.integration, cache_key: t.cache_key, max_staleness_seconds: t.max_staleness_seconds,
  degrade_reason: 'rate_limit_exhausted', retry_after_seconds: body.retry_after_seconds || C.DEGRADE_RETRY_AFTER_SECONDS } }];

const t = $json;
return [{ json: { integration: t.integration, cache_key: t.cache_key, max_staleness_seconds: t.max_staleness_seconds,
  degrade_reason: 'breaker_open', retry_after_seconds: Math.max(1, Math.round((t.next_probe_at - Date.now()) / 1000)) } }];

const C = $('CONFIG').first().json;
const t = $json;
return [{ json: { integration: t.integration, cache_key: t.cache_key, max_staleness_seconds: t.max_staleness_seconds, degrade_reason: 'probe_in_progress', retry_after_seconds: C.PROBE_IN_PROGRESS_RETRY_AFTER_SECONDS } }];

const t = $json;
return [{ json: { integration: t.integration, resource_path: t.resource_path, params: t.params, cache_key: t.cache_key,
  max_staleness_seconds: t.max_staleness_seconds, is_probe: t.is_probe, attempt: t.attempt,
  network_error: true, error_message: (t.error && t.error.message) || 'connection error', statusCode: null, body: null } }];

const t = $json;
let classification;
if (t.network_error) classification = 'transient';
else if (t.statusCode === 429) classification = 'rate_limited';
else if (t.statusCode >= 200 && t.statusCode < 300) classification = 'success';
else if (t.statusCode >= 500) classification = 'transient';
else classification = 'permanent'; // other 4xx -- our request is wrong, the provider is fine
return [{ json: { integration: t.integration, resource_path: t.resource_path, params: t.params, cache_key: t.cache_key,
  max_staleness_seconds: t.max_staleness_seconds, is_probe: t.is_probe, attempt: t.attempt,
  statusCode: t.statusCode, body: t.body, headers: t.headers || {}, classification } }];

const C = $('CONFIG').first().json;
const t = $json;
const raw = (t.headers && (t.headers['retry-after'] || t.headers['Retry-After'])) || null;
let secs = C.RETRY_AFTER_DEFAULT_SECONDS;               // used when the provider sent no usable header
if (raw) {
  const asInt = parseInt(raw, 10);
  if (!Number.isNaN(asInt) && String(asInt) === String(raw).trim()) secs = asInt;        // seconds form
  else { const d = new Date(raw); if (!isNaN(d.getTime())) secs = Math.max(1, Math.round((d.getTime() - Date.now()) / 1000)); } // HTTP-date form
}
return [{ json: { ...t, retry_after_seconds: Math.min(secs, C.RETRY_AFTER_CAP_SECONDS) } }];

const C = $('CONFIG').first().json;
const t = $json;
const backoff_ms = C.BACKOFF_BASE_MS * Math.pow(2, t.attempt - 1);
const jitter_ms = Math.floor(Math.random() * C.BACKOFF_JITTER_MS);
return [{ json: { ...t, wait_seconds: Math.round((backoff_ms + jitter_ms) / 100) / 10 } }];

const C = $('CONFIG').first().json;
const t = $json;
return [{ json: { integration: t.integration, cache_key: t.cache_key, max_staleness_seconds: t.max_staleness_seconds, degrade_reason: t.is_probe ? 'probe_failed' : 'transient_retries_exhausted', retry_after_seconds: C.DEGRADE_RETRY_AFTER_SECONDS } }];

const t = $json;
const found = t.statusCode >= 200 && t.statusCode < 300 && t.body && t.body.cached_at;
const age_seconds = found ? Math.round((Date.now() - t.body.cached_at) / 1000) : null;
const within_tolerance = t.max_staleness_seconds == null ? true : (age_seconds !== null && age_seconds <= t.max_staleness_seconds);
const usable = Boolean(found) && within_tolerance;
let cached_body = null;
if (found) { try { cached_body = JSON.parse(t.body.body); } catch (e) { cached_body = t.body.body; } }
return [{ json: { usable, cached_body, age_seconds, degrade_reason: t.degrade_reason, retry_after_seconds: t.retry_after_seconds } }];
